        return [text]

    words = text.split()
    result = []
    current_line = ""

    for word in words:
        if len(current_line) + len(word) > width:
            result.append(current_line.strip())
            current_line = word
        else:
            current_line += " " + word

    result.append(current_line.strip())
    return result

