def trace(capacity, ops):
    lru = []
    cache = {}
    results = []
    evicted_keys = []
    hits = 0
    misses = 0

    for op, key, value in ops:
        if op == "put":
            if key in cache:
                hits += 1
            else:
                lru.append(key)
                cache[key] = value
        elif op == "get":
            if key in cache:
                hits += 1
                lru.remove(key)
                lru.append(key)
                results.append(cache[key])
            else:
                misses += 1
                results.append(None)
        elif op == "peek":
            if key in cache:
                hits += 1
                results.append(cache[key])
            else:
                misses += 1
                results.append(None)

    for _ in range(len(lru)):
        if _ < capacity:
            evicted_keys.append(lru.pop(0))

    return {
        "results": results,
        "evicted": evicted_keys,
        "hits": hits,
        "misses": misses
    }

